def residual_audit_tables(raw, seconds, saved):
    """Exact historical profile arithmetic, with all squared-distance terms saved."""
    global CANON_DF,time_sorted,FEATURE_SCOPES,ACTIVE_TIERS,P0_PROFILE_COLS,TIER_ALIASES,CFG
    prior={k:globals().get(k) for k in ['CANON_DF','time_sorted','FEATURE_SCOPES','ACTIVE_TIERS','P0_PROFILE_COLS','TIER_ALIASES','CFG']}
    try:
        TIER_ALIASES=saved['cfg']['tier_aliases'];FEATURE_SCOPES=saved['scopes'];ACTIVE_TIERS=saved['active_tiers']
        P0_PROFILE_COLS=saved['plan']['profile_columns'];CFG=saved['cfg']
        vals=raw.astype(np.float32);CANON_DF=vals.replace([np.inf,-np.inf],np.nan).fillna(0)
        time_sorted=np.asarray(seconds,float)
        blocks=[np.arange(b['start'],b['end']) for b in saved['plan']['blocks']]
        profiles,pairs=match_p0_blocks(blocks)
        names=sorted(profiles.columns);matrix=profiles[names].to_numpy(float)
        center=np.median(matrix,axis=0);mad=np.median(np.abs(matrix-center),axis=0)*1.4826
        scale=mad.copy();scale[scale<1e-8]=1.0;z=(matrix-center)/scale
        scale_rows=[{'profile_field':c,'median':center[j],'raw_MAD_scale':mad[j],'applied_scale':scale[j],'scale_replaced_by_one':bool(mad[j]<1e-8)} for j,c in enumerate(names)]
        values=[]
        for i,ids in enumerate(blocks):
            for col in P0_PROFILE_COLS:
                v=CANON_DF.iloc[ids][col].to_numpy(float);q=robust_iqr(v)
                values.append({'block_id':i,'feature':col,'mean_after_historical_imputation':v.mean(),'IQR':q,'applied_IQR_denominator':max(q,1e-6),'IQR_floor_used':q<1e-6,'zero_rate':np.mean(v==0),'nonfinite_rate_before_imputation':float(np.mean(~np.isfinite(raw.iloc[ids][col].to_numpy(float))))})
        saved_lookup={p['pair_id']:p for p in saved['plan']['pairs']};contrib=[];checks=[]
        for p in pairs:
            a=p['source_block'];b=p['target_block'];old=saved_lookup.get(p['pair_id'],{})
            squared=(z[a]-z[b])**2;total=squared.sum()
            checks.append({**p,'recorded_distance':old.get('profile_distance'),'same_target_as_saved':b==old.get('target_block'),'same_phase_as_saved':p['phase']==old.get('phase'),'distance_reproduced':bool(np.isclose(p['profile_distance'],old.get('profile_distance',np.nan),rtol=1e-6,atol=1e-6))})
            for j,c in enumerate(names):
                contrib.append({'pair_id':p['pair_id'],'profile_field':c,'source_profile':matrix[a,j],'target_profile':matrix[b,j],'raw_profile_difference':matrix[a,j]-matrix[b,j],'applied_MAD_scale':scale[j],'standardised_difference':z[a,j]-z[b,j],'squared_distance_contribution':squared[j],'fraction_of_squared_distance':squared[j]/total if total else 0.})
        # Diagnostic comparison only. Global TRAIN scaling is not used to replace any match.
        diagnostics=[]
        for col in P0_PROFILE_COLS:
            train_v=CANON_DF[col].to_numpy(float);q=robust_iqr(train_v)
            for old in saved['plan']['pairs']:
                a=train_v[old['source_start']:old['source_end']];b=train_v[old['target_start']:old['target_end']]
                diagnostics.append({'pair_id':old['pair_id'],'feature':col,'source_mean':a.mean(),'target_mean':b.mean(),'global_train_IQR':q,'mean_difference_in_global_IQR_units':(a.mean()-b.mean())/q if q>0 else np.nan,'KS_distance':stats.ks_2samp(a,b,method='asymp').statistic,'zero_rate_difference':np.mean(a==0)-np.mean(b==0),'diagnostic_only':True})
        return {'profiles':profiles.assign(block_id=range(len(profiles))),'scales':scale_rows,'blocks':values,'pairs':checks,'contributions':contrib,'raw_differences':diagnostics}
    finally:
        for k,v in prior.items():
            if v is None:globals().pop(k,None)
            else:globals()[k]=v


def run_residential_audit():
    out=OUTPUT_ROOT/'residential_matching';out.mkdir(parents=True,exist_ok=True)
    saved=ASSETS['residential'];expected=saved['raw']['source_sha256']
    if not RESIDENTIAL_DATA.is_file():
        result={'status':'INPUT_UNAVAILABLE','reason':'Residential source file not found. The external run can continue, but this weakness is unresolved.','path':str(RESIDENTIAL_DATA)}
        atomic_json(out/'audit_status.json',result);progress(result['reason']);return result
    progress('Hashing the residential input. This is a one-time sequential read.')
    actual=file_hash(RESIDENTIAL_DATA)
    if actual!=expected:
        result={'status':'INPUT_DIFFERS_FROM_RECORDED_RUN','actual_sha256':actual,'expected_sha256':expected,'reason':'Historical matches cannot be claimed to be reconstructed from a different input. No matching rule was changed.'}
        atomic_json(out/'audit_status.json',result);progress(result['reason']);return result
    bound=max(b['end'] for b in saved['plan']['blocks'])
    cols=sorted(set(saved['scopes']['all_value_v3'])|set(saved['plan']['profile_columns']))
    # Read column by column to avoid a second multi-GB copy of the complete data.
    sec=read_table(RESIDENTIAL_DATA,[saved['raw']['time_column']]).iloc[:,0].to_numpy(float)
    order=np.argsort(sec,kind='stable');selected=order[:bound];seconds=sec[selected]
    if not np.all(np.diff(sec[order])>0):raise RuntimeError('Residential times are not unique.')
    matrix={}
    for i,col in enumerate(cols):
        matrix[col]=read_table(RESIDENTIAL_DATA,[col]).iloc[selected,0].to_numpy(dtype=np.float32)
        if (i+1)%100==0:progress(f'Residential audit: loaded {i+1}/{len(cols)} TRAIN columns.')
    raw=pd.DataFrame(matrix);result=residual_audit_tables(raw,seconds,saved)
    for name,rows in result.items():table(out/(name+'.csv'),rows)
    c=pd.DataFrame(result['contributions']);top=c.sort_values('fraction_of_squared_distance',ascending=False).groupby('pair_id',sort=False).head(5)
    table(out/'largest_contributors.csv',top)
    checks=pd.DataFrame(result['pairs']);ok=bool(checks[['same_target_as_saved','same_phase_as_saved','distance_reproduced']].all().all())
    status={'status':'RECONSTRUCTED' if ok else 'RECONSTRUCTION_DIFFERENCE','source_sha256':actual,'pairs':len(checks),'all_recorded_matches_reproduced':ok,'original_matches_changed':False,'interpretation':'Distance contributions and raw-value comparisons are available. Numerical reconstruction does not establish that the matched blocks are substantively similar. Inspect the largest contributors before deciding whether any residential results need recalculation.'}
    atomic_json(out/'audit_status.json',status);progress(status['status']);return status

matching_helpers:
def column_prefix(column: str) -> str:
    return column.split("__", 1)[0].lower() if "__" in column else ""

def infer_tier(column: str) -> str:
    prefix = column_prefix(column)
    if not prefix:
        return "other"
    if prefix in TIER_ALIASES:
        return TIER_ALIASES[prefix]
    for alias in sorted(TIER_ALIASES, key=len, reverse=True):
        suffix = prefix[len(alias):] if prefix.startswith(alias) else ""
        if suffix and suffix.isdigit():
            return TIER_ALIASES[alias]
    return "other"

def signal_class(column: str) -> str:
    """Semantic signal class used for capability breadth and balanced estimands."""
    value = column.lower()
    if column.endswith("__nonfinite_mask"):
        return "observability"
    if any(token in value for token in ("byte", "octet", "payload_len", "frame_len")):
        return "byte_volume"
    if any(token in value for token in (
        "mgmt", "management", "assoc", "deauth", "disassoc", "probe",
        "auth", "beacon", "channel", "permit_join", "route_request",
    )):
        return "management_control"
    if any(token in value for token in (
        "state", "event", "onoff", "open", "close", "motion", "occupancy",
        "switch", "contact", "presence", "alarm",
    )):
        return "state_event"
    if any(token in value for token in (
        "reset", "retrans", "retry", "lost", "drop", "error", "failure",
        "unreachable", "timeout", "duplicate_ack",
    )):
        return "reliability"
    if any(token in value for token in ("rssi", "lqi", "snr", "noise", "signal_strength")):
        return "radio_quality"
    if any(token in value for token in (
        "temperature", "humidity", "power", "voltage", "current", "energy",
        "pressure", "co2", "light", "illuminance",
    )):
        return "physical_context"
    if any(token in value for token in (
        "packet", "frame", "segment", "datagram", "count", "request", "response",
        "syn", "ack", "icmp", "dns", "tcp", "udp", "quic",
    )):
        return "packet_count"
    return "protocol_other"

def p0_block_profile(indices: np.ndarray) -> dict[str, float]:
    frame = CANON_DF.iloc[indices]
    profile: dict[str, float] = {}
    for tier in sorted(ACTIVE_TIERS):
        columns = [column for column in FEATURE_SCOPES["all_value_v3"] if infer_tier(column) == tier]
        if columns:
            values = frame[columns].to_numpy(dtype=np.float32)
            profile[f"tier_active__{tier}"] = float(np.mean(values != 0))
    for signal in sorted({signal_class(column) for column in P0_PROFILE_COLS}):
        columns = [column for column in P0_PROFILE_COLS if signal_class(column) == signal]
        if columns:
            values = frame[columns].to_numpy(dtype=np.float32)
            profile[f"signal_active__{signal}"] = float(np.mean(values != 0))
    for column in P0_PROFILE_COLS:
        values = frame[column].to_numpy(dtype=float)
        scale = max(robust_iqr(values), 1e-6)
        profile[f"mean__{column}"] = float(np.mean(values) / scale)
        profile[f"zero__{column}"] = float(np.mean(values == 0))
    seconds = time_sorted[indices]
    phase = (seconds % 86400.0) / 86400.0 * 2 * np.pi
    profile["tod_sin"] = float(np.mean(np.sin(phase)))
    profile["tod_cos"] = float(np.mean(np.cos(phase)))
    return profile

def match_p0_blocks(blocks: Sequence[np.ndarray]) -> tuple[pd.DataFrame, list[dict[str, Any]]]:
    profiles = [p0_block_profile(block) for block in blocks]
    columns = sorted(set().union(*(profile.keys() for profile in profiles)))
    matrix = np.asarray([[profile.get(column, 0.0) for column in columns] for profile in profiles], dtype=float)
    center = np.median(matrix, axis=0)
    scale = np.median(np.abs(matrix - center), axis=0) * 1.4826
    scale[scale < 1e-8] = 1.0
    z = (matrix - center) / scale
    midpoint = len(blocks) // 2
    left = list(range(midpoint))
    available_right = set(range(midpoint, len(blocks)))
    pairs: list[dict[str, Any]] = []
    for left_index in left:
        if not available_right:
            break
        right_index = min(
            available_right,
            key=lambda candidate: (float(np.linalg.norm(z[left_index] - z[candidate])), candidate),
        )
        available_right.remove(right_index)
        pairs.append({
            "pair_id": f"pair{len(pairs)}",
            "source_block": left_index,
            "target_block": right_index,
            "profile_distance": float(np.linalg.norm(z[left_index] - z[right_index])),
            "source_start": int(blocks[left_index][0]),
            "source_end": int(blocks[left_index][-1]) + 1,
            "target_start": int(blocks[right_index][0]),
            "target_end": int(blocks[right_index][-1]) + 1,
        })
        if len(pairs) >= int(CFG["p0_pairs"]):
            break
    if len(pairs) < 2:
        raise RuntimeError("Matched-block P0 produced fewer than two block pairs")
    calibration_count = max(1, int(round(len(pairs) * CFG["p0_calibration_fraction"])))
    calibration_count = min(calibration_count, len(pairs) - 1)
    pairs = sorted(pairs, key=lambda row: (row["profile_distance"], row["pair_id"]))
    # Balance profile distance across calibration and qualification. Assigning all
    # closest pairs to calibration would under-estimate natural real-to-real
    # variation and make the held-out qualification set systematically harder.
    calibration_indices = list(range(0, len(pairs), 2))[:calibration_count]
    if len(calibration_indices) < calibration_count:
        calibration_indices.extend(
            index for index in range(len(pairs))
            if index not in set(calibration_indices)
        )
        calibration_indices = calibration_indices[:calibration_count]
    calibration_indices = set(calibration_indices)
    for index, pair in enumerate(pairs):
        pair["phase"] = "calibration" if index in calibration_indices else "qualification"
    return pd.DataFrame(profiles), pairs

legacy_generators:
def real_row_resample(X,n,rng):
    idx=rng.integers(0,len(X),size=n)
    return X[idx].copy(),{"sample_indices_preview":idx[:100].tolist()}

def real_contiguous_block(X,n,rng):
    if n>=len(X): s=0; Y=X.copy()
    else: s=int(rng.integers(0,len(X)-n+1)); Y=X[s:s+n].copy()
    return Y,{"base_start":s,"base_length":len(Y)}

def independent_marginals(X,n,rng):
    Y=np.empty((n,X.shape[1]))
    for j in range(X.shape[1]): Y[:,j]=X[rng.integers(0,len(X),size=n),j]
    return Y,{}

def column_shuffle(X,n,rng):
    if n>=len(X): s=0; base=X.copy()
    else: s=int(rng.integers(0,len(X)-n+1)); base=X[s:s+n].copy()
    Y=base.copy()
    for j in range(Y.shape[1]): rng.shuffle(Y[:,j])
    return Y,{"base_start":s,"base_length":len(base),"base_block":base}

def hurdle_iid(X,n,rng):
    Y=np.empty((n,X.shape[1]))
    for j in range(X.shape[1]):
        col=X[:,j]; nz=col[col!=0]; p0=float(np.mean(col==0)); z=rng.random(n)<p0
        vals=nz[rng.integers(0,len(nz),size=n)] if len(nz) else np.zeros(n)
        vals=np.asarray(vals,float); vals[z]=0; Y[:,j]=vals
    return Y,{}

def independent_stitch(X,n,rng,chunk=60):
    Y=np.empty((n,X.shape[1]))
    for j in range(X.shape[1]):
        pieces=[];remain=n
        while remain>0:
            k=min(chunk,remain); s=0 if len(X)<=k else int(rng.integers(0,len(X)-k+1))
            pieces.append(X[s:s+k,j]); remain-=k
        Y[:,j]=np.concatenate(pieces)
    return Y,{"chunk_rows":chunk}

def shared_stitch(X,n,rng,chunk=60):
    pieces=[];starts=[];remain=n
    while remain>0:
        k=min(chunk,remain); s=0 if len(X)<=k else int(rng.integers(0,len(X)-k+1))
        pieces.append(X[s:s+k]); starts.append(s); remain-=k
    return np.vstack(pieces),{"chunk_rows":chunk,"chunk_starts_preview":starts[:100]}

def learned_gmm_overlay(X,n,rng):
    base,_=hurdle_iid(X,n,rng)
    idx=[feature_index[c] for c in LEARNED_SCOPE if c in feature_index]
    if not idx:return base,{"learned_scope_size":0}
    Z=X[:,idx]; scaler=StandardScaler().fit(Z); Zs=scaler.transform(Z)
    k=min(8,max(1,len(Zs)//1000))
    gmm=GaussianMixture(n_components=k,covariance_type="diag",random_state=int(rng.integers(0,2**31-1)),max_iter=150,reg_covar=1e-5).fit(Zs)
    samp,_=gmm.sample(n); vals=scaler.inverse_transform(samp); vals=np.clip(vals,Z.min(axis=0),Z.max(axis=0)); base[:,idx]=vals
    return base,{"learned_scope_size":len(idx),"components":k}

def learned_latent_var_overlay(X,n,rng):
    base,_=shared_stitch(X,n,rng)
    idx=[feature_index[c] for c in LEARNED_SCOPE if c in feature_index]
    if not idx:return base,{"learned_scope_size":0}
    Z=X[:,idx]; scaler=StandardScaler().fit(Z); Zs=scaler.transform(Z)
    ncomp=min(16,Zs.shape[1],max(2,Zs.shape[0]//500)); pca=PCA(n_components=ncomp,random_state=0).fit(Zs); L=pca.transform(Zs)
    lags=[1,5,30]; maxlag=max(lags); XX=[];YY=[]
    for t in range(maxlag,len(L)):
        XX.append(np.concatenate([L[t-l] for l in lags])); YY.append(L[t])
    reg=Ridge(alpha=1.0).fit(np.asarray(XX),np.asarray(YY))
    hist=[L[max(0,len(L)-maxlag+i)].copy() for i in range(maxlag)]; out=np.empty((n,ncomp))
    for t in range(n):
        feat=np.concatenate([hist[-l] for l in lags]); cur=reg.predict(feat.reshape(1,-1))[0]+rng.normal(0,0.05,size=ncomp)
        out[t]=cur; hist.append(cur)
    vals=scaler.inverse_transform(pca.inverse_transform(out)); vals=np.clip(vals,Z.min(axis=0),Z.max(axis=0)); base[:,idx]=vals
    return base,{"learned_scope_size":len(idx),"latent_components":ncomp}

def generic_health(reference,syn):
    tr_std=np.std(reference,axis=0); sy_std=np.std(syn,axis=0); variable=tr_std>1e-9
    vf=float(np.mean(sy_std[variable]>1e-9)) if variable.any() else 1.0
    support=float(np.mean((syn<reference.min(axis=0))|(syn>reference.max(axis=0))))
    a=np.abs(np.mean(syn==0,axis=0)-np.mean(reference==0,axis=0))
    return {"finite":bool(np.isfinite(syn).all()),"variable_fraction":vf,"support_violation":support,
            "activity_error_mean":float(np.mean(a)),"activity_error_p95":float(np.quantile(a,.95)),"activity_error_max":float(np.max(a))}

def exact_column_multiset_equal(A,B):
    if A.shape!=B.shape:return False,np.inf
    mx=0.0
    for j in range(A.shape[1]):
        a=np.sort(A[:,j]); b=np.sort(B[:,j]); d=float(np.max(np.abs(a-b))) if len(a) else 0.0; mx=max(mx,d)
        if not np.array_equal(a,b):return False,mx
    return True,mx

def validate_contract(source,Xtr,syn,meta):
    contract=SOURCE_CONTRACT[source]; base={"contract":contract}
    if not np.isfinite(syn).all():
        return {**base,"contract_state":"Execution-Invalid","contract_valid":False,"promotion_permission":"DIAGNOSTIC_ONLY","reason":"non-finite output"}
    if contract=="REAL_SAMPLING_ANCHOR":
        support=float(np.mean((syn<Xtr.min(axis=0))|(syn>Xtr.max(axis=0)))); ok=bool(support==0 and syn.shape[1]==Xtr.shape[1])
        return {**base,"support_violation":support,"contract_state":"Anchor-Valid" if ok else "Anchor-Invalid","contract_valid":ok,"promotion_permission":"ANCHOR_EVIDENCE" if ok else "DIAGNOSTIC_ONLY"}
    if contract=="REAL_CHRONOLOGICAL_ANCHOR":
        s=int(meta["base_start"]); n=int(meta["base_length"]); exact=bool(np.array_equal(syn,Xtr[s:s+n])); ok=bool(exact and n==len(syn))
        return {**base,"base_start":s,"base_length":n,"exact_contiguous_block":exact,"contract_state":"Anchor-Valid" if ok else "Anchor-Invalid","contract_valid":ok,"promotion_permission":"ANCHOR_EVIDENCE" if ok else "DIAGNOSTIC_ONLY"}
    if contract=="MARGINAL_DESTRUCTION_MECHANISM":
        h=generic_health(Xtr,syn); ok=bool(h["support_violation"]<=1e-12 and h["variable_fraction"]>=0.95 and h["activity_error_mean"]<=0.03 and h["activity_error_max"]<=0.10)
        return {**base,**h,"contract_state":"Mechanism-Valid" if ok else "Mechanism-Invalid","contract_valid":ok,"promotion_permission":"MECHANISM_EVIDENCE" if ok else "DIAGNOSTIC_ONLY"}
    if contract=="COLUMN_SHUFFLE_INVARIANT":
        B=meta["base_block"]; multiset,maxdiff=exact_column_multiset_equal(B,syn)
        zr=float(np.max(np.abs(np.mean(B==0,axis=0)-np.mean(syn==0,axis=0)))); std=float(np.max(np.abs(np.std(B,axis=0)-np.std(syn,axis=0))))
        same=float(np.mean([np.mean(B[:,j]==syn[:,j]) for j in range(B.shape[1])])); destroyed=bool(same<0.99)
        # Exact column-multiset equality already guarantees identical marginal values; the recomputed std difference is retained only as an audit diagnostic because floating-point reduction can introduce sub-nanoscopic rounding differences.
        ok=bool(multiset and zr<=1e-12 and destroyed)
